diff --git a/.github/workflows/playwright.yml b/.github/workflows/playwright.yml
index 01b6031..afa303f 100644
--- a/.github/workflows/playwright.yml
+++ b/.github/workflows/playwright.yml
@@ -45,19 +45,26 @@ jobs:
           path: playwright-report/
           retention-days: 30

-  # Publishes to the gh-pages branch: root = newest report, /runs/<n>/ = archive.
-  # main only — a PR publish would overwrite main's report, and a fork PR would
-  # fail outright on the missing write permission.
+  # Publishes to the gh-pages branch. Every run is archived under /runs/<n>/ and
+  # listed in history.html; only main also claims the root URL, so the site's
+  # front page stays "latest on main" rather than whichever branch ran last.
+  #
+  # Skipped for pull requests from forks: those get a read-only token and would
+  # fail on the contents: write below.
   publish-report:
     name: Publish report to Pages
     needs: test
     # `always()` so a failing test run still publishes its (red) report — a
     # report you only get when tests pass is a report you can't debug with.
-    if: ${{ always() && github.ref == 'refs/heads/main' && github.event_name != 'pull_request' }}
+    if: >-
+      ${{ always() &&
+          (github.event_name != 'pull_request' ||
+           github.event.pull_request.head.repo.full_name == github.repository) }}
     runs-on: ubuntu-latest
     timeout-minutes: 10
     permissions:
       contents: write
+      pull-requests: write
     steps:
       # The publish script lives on the source branch, not on gh-pages, so it is
       # checked out separately into its own directory.
@@ -82,7 +89,10 @@ jobs:
           name: playwright-report-${{ github.run_number }}
           path: pages/runs/${{ github.run_number }}

+      # Only main claims the root: a PR run is archived and indexed, but must not
+      # replace the front page, which represents the state of the main branch.
       - name: Copy report to site root as latest
+        if: ${{ github.ref == 'refs/heads/main' }}
         working-directory: pages
         run: |
           set -euo pipefail
@@ -103,7 +113,10 @@ jobs:
           RUN: ${{ github.run_number }}
           STATUS: ${{ needs.test.result }}
           SHA: ${{ github.sha }}
-          REF: ${{ github.ref_name }}
+          # On a pull request github.ref_name is "<number>/merge"; use the source
+          # branch instead so the history table reads meaningfully.
+          REF: ${{ github.head_ref || github.ref_name }}
+          PR: ${{ github.event.pull_request.number }}
           ACTOR: ${{ github.actor }}
           SERVER: ${{ github.server_url }}
           REPO: ${{ github.repository }}
@@ -121,3 +134,40 @@ jobs:
           git diff --staged --quiet && echo "nothing to publish" && exit 0
           git commit -m "Publish report for run #${{ github.run_number }} (${{ needs.test.result }})"
           git push "https://x-access-token:${{ secrets.GITHUB_TOKEN }}@github.com/${GITHUB_REPOSITORY}.git" gh-pages
+
+      # One comment per PR, edited in place on re-runs rather than appended, so
+      # a branch with several pushes doesn't accumulate a wall of bot comments.
+      - name: Comment report link on the pull request
+        if: ${{ github.event_name == 'pull_request' }}
+        uses: actions/github-script@v7
+        with:
+          script: |
+            const run = context.runNumber;
+            const passed = '${{ needs.test.result }}' === 'success';
+            const url =
+              `https://${context.repo.owner}.github.io/${context.repo.repo}/runs/${run}/`;
+            const marker = '<!-- playwright-report-link -->';
+            const body =
+              `${marker}\n### Playwright report — ${passed ? '✅ passed' : '❌ failed'}\n\n` +
+              `[View the report for run #${run}](${url})\n\n` +
+              `<sub>Updated automatically on each push to this branch.</sub>`;
+
+            const { data: comments } = await github.rest.issues.listComments({
+              ...context.repo,
+              issue_number: context.issue.number,
+            });
+            const existing = comments.find((comment) => comment.body.includes(marker));
+
+            if (existing) {
+              await github.rest.issues.updateComment({
+                ...context.repo,
+                comment_id: existing.id,
+                body,
+              });
+            } else {
+              await github.rest.issues.createComment({
+                ...context.repo,
+                issue_number: context.issue.number,
+                body,
+              });
+            }
diff --git a/scripts/publish-report.mjs b/scripts/publish-report.mjs
index 7273913..3f155e1 100644
--- a/scripts/publish-report.mjs
+++ b/scripts/publish-report.mjs
@@ -49,6 +49,8 @@ function buildEntry() {
     status: requireEnv('STATUS'),
     sha: requireEnv('SHA').slice(0, 7),
     ref: requireEnv('REF'),
+    // Only set on pull-request runs; absent for pushes to main.
+    pr: process.env.PR ? Number(process.env.PR) : null,
     actor: requireEnv('ACTOR'),
     date: new Date().toISOString(),
     workflowUrl: `${server}/${repo}/actions/runs/${runId}`,
@@ -84,11 +86,14 @@ function escapeHtml(value) {
 function renderRow(entry) {
   const passed = entry.status === 'success';
   const timestamp = String(entry.date).replace('T', ' ').slice(0, 16);
+  const source = entry.pr
+    ? `<span class="pr">PR #${escapeHtml(entry.pr)}</span> ${escapeHtml(entry.ref)}`
+    : escapeHtml(entry.ref);

   return `      <tr>
         <td><a href="runs/${escapeHtml(entry.run)}/index.html">#${escapeHtml(entry.run)}</a></td>
         <td class="${passed ? 'ok' : 'bad'}">${passed ? 'passed' : escapeHtml(entry.status)}</td>
-        <td>${escapeHtml(entry.ref)}</td>
+        <td>${source}</td>
         <td><code>${escapeHtml(entry.sha)}</code></td>
         <td>${escapeHtml(timestamp)} UTC</td>
         <td><a href="${escapeHtml(entry.workflowUrl)}">workflow</a></td>
@@ -137,6 +142,12 @@ function renderIndex(history) {
       .bad {
         color: #c02626;
       }
+      .pr {
+        font-size: 0.75rem;
+        padding: 0.1em 0.4em;
+        border-radius: 3px;
+        background: #8883;
+      }
       @media (prefers-color-scheme: dark) {
         .ok {
           color: #4ade80;
@@ -149,7 +160,10 @@ function renderIndex(history) {
   </head>
   <body>
     <h1>Playwright report history</h1>
-    <p><a href="index.html">Latest report</a> — newest ${history.length} runs on main.</p>
+    <p>
+      <a href="index.html">Latest report on main</a> — newest ${history.length} runs,
+      including pull requests.
+    </p>
     <table>
       <thead>
         <tr>

